-- Requires matching executable with SMARTCAST_RETRY_LINK0x200; keep outside live updater until promotion.
-- Retry only rejected linked Wardstone199770/187027 casts; never replay root205/48172.
-- Preserve native ordinary casts, admission, unknownLINK4, base payload and all MistWarder behavior.
SET @ward_retry_saved_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
